const clone=v=>structuredClone(v);const uid=(p='clip')=>`${p}_${globalThis.crypto?.randomUUID?.()??Math.random().toString(36).slice(2)}`;
function get(p,id){return p.clips?.find(c=>c.id===id);}function assertEdit(p,c){if(!c)throw new Error('Clip not found.');const t=p.tracks?.find(x=>x.id===c.trackId);if(c.locked||t?.locked)throw new Error('Clip or track is locked.');}
export function canEditTrack(project,trackId){return !project.tracks?.find(t=>t.id===trackId)?.locked;}
export function splitClip(project,clipId,timeUs){const p=clone(project),c=get(p,clipId);assertEdit(p,c);timeUs=Math.round(timeUs);if(timeUs<=c.startUs||timeUs>=c.endUs)throw new Error('Split point must be inside clip.');const i=p.clips.findIndex(x=>x.id===clipId),delta=timeUs-c.startUs,a=clone(c),b=clone(c);a.id=uid();b.id=uid();a.endUs=timeUs;a.sourceOutUs=(c.sourceInUs||0)+delta;b.startUs=timeUs;b.sourceInUs=(c.sourceInUs||0)+delta;b.sourceOutUs=c.sourceOutUs??((c.sourceInUs||0)+(c.endUs-c.startUs));a.fadeOutUs=Math.min(a.fadeOutUs||0,a.endUs-a.startUs);b.fadeInUs=Math.min(b.fadeInUs||0,b.endUs-b.startUs);p.clips.splice(i,1,a,b);return p;}
export function trimClip(project,clipId,{startUs,endUs}){const p=clone(project),c=get(p,clipId);assertEdit(p,c);const oldStart=c.startUs,oldEnd=c.endUs,ns=Math.max(0,Math.round(startUs??oldStart)),ne=Math.round(endUs??oldEnd);if(ne<=ns)throw new Error('Trim range is invalid.');const startDelta=ns-oldStart,endDelta=oldEnd-ne;c.startUs=ns;c.endUs=ne;c.sourceInUs=Math.max(0,(c.sourceInUs||0)+startDelta);c.sourceOutUs=Math.max(c.sourceInUs,(c.sourceOutUs??((c.sourceInUs||0)+(oldEnd-oldStart)))-endDelta);const d=ne-ns;c.fadeInUs=Math.min(c.fadeInUs||0,d);c.fadeOutUs=Math.min(c.fadeOutUs||0,d-c.fadeInUs);return p;}
export function rippleDelete(project,clipIds){const p=clone(project),set=new Set(clipIds),targets=(p.clips||[]).filter(c=>set.has(c.id));targets.forEach(c=>assertEdit(p,c));const byTrack=new Map();for(const c of targets){const a=byTrack.get(c.trackId)||[];a.push(c);byTrack.set(c.trackId,a);}p.clips=p.clips.filter(c=>!set.has(c.id));for(const [trackId,removed] of byTrack){const start=Math.min(...removed.map(c=>c.startUs)),end=Math.max(...removed.map(c=>c.endUs)),span=end-start;for(const c of p.clips){if(c.trackId!==trackId||c.startUs<end)continue;if(c.locked)continue;c.startUs-=span;c.endUs-=span;}}return p;}
export function setClipFade(project,clipId,{fadeInUs,fadeOutUs}){const p=clone(project),c=get(p,clipId);assertEdit(p,c);const d=c.endUs-c.startUs;let a=Math.max(0,Math.min(d,Math.round(fadeInUs??c.fadeInUs??0))),b=Math.max(0,Math.min(d,Math.round(fadeOutUs??c.fadeOutUs??0)));if(a+b>d){const r=d/(a+b||1);a=Math.floor(a*r);b=d-a;}c.fadeInUs=a;c.fadeOutUs=b;return p;}
export function setClipLabel(project,clipId,label){const p=clone(project),c=get(p,clipId);assertEdit(p,c);c.label=String(label??'').slice(0,64);return p;}
export function toggleKeyframeAt(project,clipId,property,timeUs,value){const p=clone(project),c=get(p,clipId);assertEdit(p,c);c.keyframes=Array.isArray(c.keyframes)?c.keyframes:[];const t=Math.round(timeUs);const i=c.keyframes.findIndex(k=>k.property===property&&k.timeUs===t);if(i>=0)c.keyframes.splice(i,1);else c.keyframes.push({id:uid('keyframe'),property,timeUs:t,value});c.keyframes.sort((a,b)=>a.timeUs-b.timeUs);return p;}
